const input = $json.body ?? $json;
const required = ['user_id', 'image_base64', 'mime_type'];
const missing = required.filter(k => !input[k]);
if (missing.length) throw new Error('Missing required fields: ' + missing.join(', '));
if (!['image/jpeg','image/png','image/webp'].includes(input.mime_type)) throw new Error('Unsupported mime_type. Use image/jpeg, image/png, or image/webp.');
const base64 = String(input.image_base64).replace(/^data:image\/[a-zA-Z0-9.+-]+;base64,/, '');
if (!/^[A-Za-z0-9+/=\r\n]+$/.test(base64)) throw new Error('image_base64 is not valid base64.');
const approxBytes = Math.floor(base64.replace(/\s/g,'').length * 3 / 4);
if (approxBytes > 8 * 1024 * 1024) throw new Error('Image exceeds 8 MB prototype limit.');
const memoryId = 'mem_' + Date.now().toString(36) + '_' + Math.random().toString(36).slice(2, 10);
return [{ json: { user_id: String(input.user_id), memory_id: memoryId, mime_type: input.mime_type, image_base64: base64.replace(/\s/g,''), user_note: input.user_note ?? '', selected_collection: input.selected_collection ?? null, created_at: new Date().toISOString(), file_url: input.file_url ?? null } }];

const base = $('Validate and Normalize').item.json;
const geminiRaw = $('Gemini Visual Analysis').item.json?.candidates?.[0]?.content?.parts?.[0]?.text ?? '{}';
const openaiText = $json?.choices?.[0]?.message?.content ?? '{}';
function parseObject(s, label) { try { const v = typeof s === 'string' ? JSON.parse(s) : s; if (!v || typeof v !== 'object' || Array.isArray(v)) throw new Error('not object'); return v; } catch (e) { throw new Error(label + ' returned invalid JSON: ' + e.message); } }
const visual = parseObject(geminiRaw, 'Gemini');
const organised = parseObject(openaiText, 'OpenAI');
const allowed = ['Family','Friends','Childhood','College','Travel','Festivals','Nature','Everyday Life','Other'];
const collection = allowed.includes(organised.suggested_collection) ? organised.suggested_collection : 'Other';
const confidence = Number(organised.collection_confidence ?? visual.confidence ?? 0);
const result = {
  memory_id: base.memory_id,
  user_id: base.user_id,
  media_type: 'image',
  file_url: base.file_url,
  description: String(visual.description ?? ''),
  timestamp: null,
  location: { name: null, latitude: null, longitude: null, confirmed: false },
  tags: Array.isArray(visual.visual_tags) ? visual.visual_tags : [],
  visible_objects: Array.isArray(visual.objects) ? visual.objects : [],
  activities: Array.isArray(visual.activities) ? visual.activities : [],
  suggested_collection: collection,
  collection_reason: String(organised.collection_reason ?? ''),
  caption: String(organised.caption ?? ''),
  short_story: String(organised.short_story ?? ''),
  confidence: Math.max(0, Math.min(1, Number.isFinite(confidence) ? confidence : 0)),
  needs_review: Boolean(organised.needs_review ?? true) || !base.file_url,
  user_approved: false,
  user_note: base.user_note,
  created_at: base.created_at,
  visual_analysis: visual,
  related_memory_search_terms: Array.isArray(organised.related_memory_search_terms) ? organised.related_memory_search_terms : [],
  processing_status: 'processed'
};
return [{json: result}];
